package fr.formation.clean.application.usecase;import fr.formation.clean.application.boundary.*;import fr.formation.clean.domain.entity.Room;import java.util.*;public final class ManageRoomInteractor implements ManageRoomInputBoundary{private final RoomGateway rooms;public ManageRoomInteractor(RoomGateway rooms){this.rooms=rooms;}public Room create(String name,int capacity){return rooms.save(new Room(UUID.randomUUID(),name,capacity));}public List<Room>list(){return rooms.findAll();}}
